import { L, info, mc, tf, fill, fillc, type, order, match } from '../_h.js';

export default {
  timeseries: [
    L('Data with a clock',
      info('What is a time series?', 'A **time series** is a list of measurements in time order: daily sales, a radar signal every 50 ms, hourly temperature.\n\nTwo things make it special:\n\n- **Order matters.** Shuffling destroys the information.\n- **Neighbours are related.** Today looks like yesterday.'),
      mc('Which of these is a time series?', ['CPU temperature logged every second', 'A table of customers and their cities', 'A folder of unrelated photos', 'A list of product names'], 'Measurements indexed by time.'),
      match('Match the component', [['Trend', 'Long-term rise or fall'], ['Seasonality', 'A pattern that repeats with a fixed period'], ['Noise', 'Random variation left over'], ['Level', 'The typical value around which it moves']]),
      mc('Ice-cream sales peak every summer. That is…', ['Seasonality', 'Trend', 'Noise', 'Drift'], 'A repeating pattern with a yearly period.'),
      mc('Sales grow steadily by about 5% every year. That is…', ['Trend', 'Seasonality', 'Noise', 'An outlier'], 'A long-term direction.'),
      info('The golden rule', 'To predict a moment in time you may only use information available **before** it.\n\nBreaking this rule is called **leakage**. It gives wonderful test scores and a useless model.'),
      tf('It is fine to shuffle a time series before splitting into train and test.', false, 'The model would train on the future and be tested on the past.'),
      mc('You have data from 2020 to 2025. A sound split is…', ['Train on 2020 to 2024, test on 2025', 'A random 80/20 split of all days', 'Train on 2025, test on 2020', 'Test on every second day'], 'Train on the past, test on the future.')),

    L('Baselines and smoothing',
      info('Start with something dumb', 'Before any model, try:\n\n- **Naive:** tomorrow = today.\n- **Seasonal naive:** next Monday = last Monday.\n- **Moving average:** the mean of the last k values.\n\nA surprising number of complex models lose to these. If yours cannot beat them, it is not ready.'),
      type('A series is 10, 12, 15, 14. What does the naive method forecast for the next value?', ['14'], 'The last observed value.'),
      type('Hourly data with a daily pattern. The seasonal-naive forecast for 9:00 tomorrow is the value at 9:00 how many hours earlier?', ['24'], 'One season back.'),
      type('What is the 3-point moving average of 4, 8, 6?', ['6', '6.0'], '(4 + 8 + 6) / 3.'),
      info('Exponential smoothing', 'A moving average treats old and new points equally. **Exponential smoothing** trusts recent points more:\n\n```\ns[t] = alpha * x[t] + (1 - alpha) * s[t-1]\n```\n\n`alpha` near 1 reacts fast and is noisy. `alpha` near 0 is smooth and slow.'),
      type('s = 10, the new value x = 20, alpha = 0.5. What is the new s?', ['15', '15.0'], '0.5 * 20 + 0.5 * 10.'),
      mc('Your smoothed signal lags badly behind sudden changes. Change alpha how?', ['Increase it', 'Decrease it', 'Set it to 0', 'It does not matter'], 'Higher alpha weights new data more.'),
      fillc('s = alpha * x + (1 - ___) * s', ['alpha', 'x', 's', '2'], 'The two weights sum to one.')),

    L('Features, windows and honest validation',
      info('From a series to a table', 'Machine-learning models want rows of features and a target. Slide a **window** along the series:\n\n- features = the last `lookback` values (lags)\n- target = the value `horizon` steps ahead\n\nAdd calendar features and rolling statistics.'),
      mc('Series [1, 2, 3, 4, 5], lookback 2, horizon 1. The first training row is…', ['features [1, 2], target 3', 'features [1, 2], target 2', 'features [2, 3], target 1', 'features [1], target 5'], 'Two values in, the next value out.'),
      type('A series has 100 points. With lookback 10 and horizon 1, how many training rows do you get?', ['90'], '100 - 10 - 1 + 1.'),
      mc('To predict today you add the feature "mean of the last 7 days including today". Problem?', ['Leakage: the feature contains the target', 'None', 'Too few features', 'It is not stationary'], 'Shift rolling features by one step.'),
      fillc('df["roll7"] = df["y"].___(1).rolling(7).mean()', ['shift', 'skip', 'lag_drop', 'head'], 'Shift first so the window ends yesterday.'),
      info('Walk-forward validation', 'One split can be lucky. Instead:\n\n1. Train up to a cut-off date.\n2. Forecast the next horizon and score it.\n3. Move the cut-off forward and repeat.\n\nAverage the scores. This is also called rolling-origin evaluation or backtesting.'),
      order('Order one round of walk-forward validation', ['Choose a cut-off date', 'Train on data before the cut-off', 'Forecast the period after the cut-off', 'Score against what really happened', 'Move the cut-off forward and repeat'], 'It imitates how the model will be used.'),
      mc('Why is MAPE risky for a product that often sells zero units?', ['Division by values near zero makes it explode', 'It is always negative', 'It ignores errors', 'It needs seasonality'], 'Use MAE or MASE instead.'),
      mc('MASE = 0.8 means…', ['Your error is 20% lower than the naive forecast', 'You are 80% accurate', 'The model is worse than naive', 'The error is 0.8 units'], 'Below 1 beats naive; above 1 loses to it.')),

    L('Models and interview level',
      info('Three families', '**Classical** (ETS, ARIMA): few series, little data, interpretable.\n\n**Gradient-boosted trees** on lag and calendar features: many series, extra covariates. Often the best practical choice.\n\n**Neural** (LSTM, temporal convolution, transformers): large data, many related series, long patterns.'),
      mc('You forecast demand for 20,000 products with prices and promotions as inputs. Good first serious model?', ['Gradient-boosted trees on lag and calendar features', 'One ARIMA fitted by hand per product', 'A random guess', 'A convolutional image model'], 'One global model across all series with covariates.'),
      match('Match ARIMA’s parts', [['AR', 'Regress on past values'], ['I', 'Difference to remove trend'], ['MA', 'Regress on past forecast errors'], ['Seasonal terms', 'Same ideas at the seasonal lag']]),
      mc('A series has a strong upward trend. Before fitting a model that assumes stationarity you…', ['Difference it', 'Shuffle it', 'Square it', 'Delete the first half'], 'Differencing turns levels into changes.'),
      tf('A stationary series has a mean and variance that do not change over time.', true, 'Many classical methods assume this.'),
      info('Drift in production', 'The world changes: a pandemic, a new competitor, a sensor replaced. A model trained on the old regime degrades.\n\nMonitor forecast error over time, retrain on a schedule or when error rises, and keep a simple fallback.'),
      mc('Forecast error rose sharply last month and stayed high. Most likely?', ['The data-generating process changed (drift)', 'The model became more accurate', 'Random noise only', 'The metric is broken by definition'], 'Investigate what changed, then retrain or adapt.'),
      order('Order a strong answer to "How do you build a forecasting system?"', ['Clarify the horizon, granularity and cost of errors', 'Build naive and seasonal-naive baselines', 'Engineer leakage-free features and backtest candidate models', 'Deploy with monitoring, retraining and a fallback'], 'Requirements, baselines, honest evaluation, operations.'),
      mc('Which is the strongest sign of leakage in a forecasting project?', ['Backtest accuracy far better than live accuracy', 'Slow training', 'A high MASE', 'A small dataset'], 'The backtest used information not available in real time.')),

    L('Autocorrelation, differencing and uncertainty',
      info('Reading the structure of a series', '**Autocorrelation** is the correlation of a series with itself shifted by k steps (lag k). Plotted against k it is the **ACF**. Peaks at lag 7, 14, 21 in daily data reveal a weekly pattern.\n\n**Differencing** subtracts the previous value: `d[t] = y[t] - y[t-1]`. It removes a trend. Differencing again removes a curved trend.\n\nIf the swings grow as the level grows, the pattern is **multiplicative**. Taking the **log** turns multiplication into addition and stabilises the variance.'),
      mc('Hourly data show ACF peaks at lags 24, 48 and 72. What does this suggest?', ['A daily seasonal pattern', 'A weekly pattern', 'No structure at all', 'A trend only'], 'The series resembles itself every 24 hours.'),
      type('A series is 100, 104, 110, 118. What is the last first difference?', ['8'], '118 - 110.'),
      mc('Monthly passenger counts rise over the years and the seasonal swings get bigger as the level rises. Which treatment fits?', ['Take logs, then model it additively', 'Subtract the mean once', 'Shuffle the months', 'Remove the last year'], 'A multiplicative pattern becomes additive in logs.'),
      fillc('y_diff = np.diff(np.___(y))   # stabilise the variance, then remove the trend', ['log', 'exp', 'cumsum', 'sort'], 'Log first, then difference.'),
      tf('Differencing a series with a steady linear trend gives a series with a roughly constant mean.', true, 'A straight line has a constant slope, so its differences are constant.'),
      info('Forecasts with error bars', 'A single number hides risk. A **prediction interval** says "80% of outcomes should fall between a and b".\n\nTo train a model for a specific quantile q (say q = 0.9, so that it is rarely too low), use the **pinball loss**: under-forecasting costs q per unit, over-forecasting costs 1 - q per unit.\n\n**Coverage** checks the intervals: a nominal 80% interval should contain about 80% of actuals in a backtest.'),
      type('Quantile q = 0.9. The actual is 100 and you forecast 90, an under-forecast of 10. What is the pinball loss?', ['9', '9.0'], '0.9 × 10.'),
      mc('Your nominal 80% intervals contain only 50% of actuals in the backtest. What does that mean?', ['The intervals are too narrow and overconfident', 'The intervals are too wide', 'The model is perfect', 'The data are stationary'], 'Recalibrate, for example from the quantiles of backtest errors.')),

    L('Common mistakes and debugging',
      info('Bugs that flatter you', 'In forecasting almost every serious bug makes the backtest **look better** than reality, so a great score deserves suspicion.\n\nThe usual sources: preprocessing fitted on the whole series, filling gaps with future values, time-zone mistakes, metrics computed on the wrong scale, and comparing models on different windows.'),
      mc('What is wrong with this code?', ['The scaler is fitted on the whole series, so the training data carry information about the future', 'Nothing is wrong', 'The test set is too small', 'StandardScaler cannot be used on series'], 'Fit on the training part only, then transform both.', 'scaler = StandardScaler().fit(df[["y"]])      # whole series\ntrain, test = df[:800], df[800:]'),
      fill('Any scaler or encoder must be fitted on the ___ data only.', ['training', 'test', 'whole', 'future'], 'Otherwise statistics from the evaluation period leak in.'),
      mc('Hourly data in local time are used for modelling. When clocks go back, what appears in the index?', ['The same hour appears twice, creating duplicate timestamps', 'One hour disappears', 'Nothing changes', 'The data become stationary'], 'Store timestamps in UTC and convert only for display.'),
      info('Gaps and metrics', 'Filling missing values backwards (`bfill`) copies a later value into an earlier row: leakage. Use forward fill, interpolation using only the past, or a model that accepts missing values.\n\nIf you train on `log(y)`, convert predictions back with `exp` before computing the error, and report errors in the original units.'),
      mc('A colleague fills gaps with `df["y"].fillna(method="bfill")`. What is the problem?', ['Each gap is filled with the next observed value, which is in the future', 'It is slower than forward fill', 'It removes the trend', 'It changes the index'], 'A forecaster could never know the next value at prediction time.'),
      tf('Comparing two models over different test periods is a fair comparison.', false, 'Easy and hard periods give different errors; evaluate on identical windows.'),
      mc('A model trained on log(y) reports an MAE of 0.07 on sales that average 300 units. What is the likely mistake?', ['The error was computed in log space instead of after converting back to units', 'The model is excellent', 'The sales data are too large', 'The trend was removed twice'], 'Back-transform before scoring.'),
      type('Your model has an MAE of 6 and the naive forecast has an MAE of 4 on the same data. What is the MASE?', ['1.5', '1.50'], '6 / 4. Above 1 means the model loses to naive.'),
      order('Order the checks when a backtest looks too good', ['Confirm the split is by time', 'Check scalers and encoders were fitted on training data only', 'Check every feature is available at forecast time, shifting rolling features', 'Check that no gap filling uses future values', 'Compare with the naive baseline on identical windows'], 'From the cheapest and most common to the most thorough.')),

    L('Case study: daily stock for a grocery chain',
      info('The problem', 'A grocery chain has 800 stores and about 3,000 products in each. Every night it orders stock for tomorrow. Too little stock loses sales; too much spoils.\n\nYou must forecast demand per store and product, one to seven days ahead.'),
      type('How many store-product series is that?', ['2400000', '2,400,000'], '800 × 3,000.'),
      mc('What is the first baseline to build?', ['Seasonal naive: the value from the same weekday last week', 'A transformer', 'The overall mean for every series', 'A random number'], 'Weekly shopping patterns make last week’s value hard to beat.'),
      mc('How do you model 2.4 million series?', ['One global gradient-boosted model with lag, calendar, price and promotion features', 'A hand-tuned ARIMA for each series', 'One model per store, tuned by hand', 'Averages by product only'], 'Sharing a model across series learns from all of them and scales.'),
      info('Costs decide the target', 'Missing a sale loses 3 units of profit per unit, while a surplus unit costs 1 unit in waste. Ordering the **average** forecast ignores this asymmetry.\n\nThe best order quantity is the quantile **q = cost_under / (cost_under + cost_over)** of the demand distribution. This is the classic newsvendor result.'),
      type('With an under-stock cost of 3 and a surplus cost of 1, which quantile q of demand should you order?', ['0.75', '75%', '.75'], '3 / (3 + 1).'),
      mc('So which forecast should the system output to drive ordering?', ['The 75th percentile of demand', 'The mean of demand', 'The minimum of demand', 'Always last week’s value'], 'Train with pinball loss at q = 0.75 or predict a distribution.'),
      order('Order the build', ['Build features that use only data up to the forecast date', 'Train a global model across all products', 'Backtest with rolling origins over several weeks', 'Compare with seasonal naive by MASE per product group', 'Deploy nightly with monitoring of error and bias'], 'Honest evaluation before deployment.'),
      match('Match the problem to the remedy', [['Stock-out days record zero sales', 'Treat them as censored, not as zero demand'], ['A brand-new product has no history', 'Borrow from similar products via category and price features'], ['A holiday moves each year', 'Calendar features such as days until the holiday'], ['Price cuts change demand', 'Price and promotion as known-future inputs']]),
      mc('The global model beats seasonal naive overall (MASE 0.85) but loses on slow-moving products (MASE 1.2). What do you do?', ['Use a method built for intermittent demand on that segment, and keep the global model elsewhere', 'Ship it unchanged', 'Delete the slow products', 'Report only the average'], 'Always slice the error by segment.')),

    L('Interview drill: forecasting judgement',
      info('What interviewers listen for', 'Forecasting questions test judgement more than formulas: do you ask what the forecast is **for**, do you distrust a great backtest, and do you know when a simple method wins?\n\nOpen with the decision the forecast supports, then the data, then the method.'),
      mc('Which metric punishes one very large miss more heavily?', ['RMSE', 'MAE', 'They are identical', 'Neither penalises large misses'], 'Squaring errors makes big ones dominate.'),
      tf('The model with the lower RMSE always produces the better business result.', false, 'Costs are often asymmetric and the metric may not match the decision.'),
      type('A trailing moving average over 5 points lags the signal by about how many steps?', ['2'], '(5 - 1) / 2.'),
      mc('Interviewer: "You forecast thousands of series with very different scales. Which metric do you use?"', ['A scale-free metric such as MASE, plus errors by segment', 'Raw MAE averaged over all series', 'Training loss', 'The largest series only'], 'Raw averages are dominated by the biggest series.'),
      match('Match the follow-up to its answer', [['ETS or ARIMA?', 'ETS models level, trend and season directly; ARIMA models the autocorrelation of a differenced series'], ['Why take logs?', 'They tame growing variance and make multiplicative effects additive'], ['How do you get prediction intervals?', 'Quantile models, residual quantiles from backtests, or simulation'], ['What is hierarchical forecasting?', 'Forecasts for product, store and total that must add up (reconciled)']]),
      info('When the data are thin', 'A new sensor or product has only a few weeks of data. A model cannot learn a yearly season from three weeks. Options: borrow strength from similar series with a **global model**, use hierarchical or category averages, or fall back on a simple baseline and say so.\n\nSaying "I would not trust a complex model here, and this is why" is a strong answer.'),
      mc('A new sensor has 3 weeks of data and you must forecast next week. Best approach?', ['A global model trained on similar sensors, or a seasonal naive baseline', 'A deep network trained on those 3 weeks alone', 'Refuse to forecast', 'A yearly seasonal model'], 'Three weeks cannot teach a yearly pattern.'),
      order('Order a strong answer to "The forecast is accurate on average but the business is unhappy"', ['Ask what decision the forecast supports', 'Slice the errors by horizon, segment and day type', 'Look at bias, not only absolute error', 'Align the metric with the cost of over- and under-forecasting', 'Add quantiles or intervals if risk matters'], 'Start from the decision, not the metric.'))
  ],

  rnn: [
    L('Why sequences need memory',
      info('Order carries meaning', '"Dog bites man" and "man bites dog" contain the same words. A sensor value of 80 means different things if the previous values were 79 or 20.\n\nA plain feed-forward network sees one input at a time with no memory. For sequences we need a model that **remembers**.'),
      mc('Which input is a sequence where order matters?', ['The words of a sentence', 'The pixels of one sorted histogram', 'A customer’s age and city', 'A single number'], 'Reordering the words changes the meaning.'),
      info('The hidden state', 'A **recurrent neural network (RNN)** reads the sequence one step at a time. It keeps a vector called the **hidden state**: its summary of everything seen so far.\n\nAt each step: take the new input and the old hidden state, produce a new hidden state.'),
      mc('What does the hidden state represent?', ['A summary of the sequence so far', 'The learning rate', 'The final loss', 'The input at the current step only'], 'It is the network’s memory.'),
      tf('An RNN uses different weights at every time step.', false, 'The same weights are reused at each step, which lets it handle any length.'),
      fillc('h = np.tanh(x @ Wx + ___ @ Wh + b)', ['h', 'x', 'b', 'Wx'], 'The previous hidden state feeds into the new one.'),
      match('Match the task to the pattern', [['Sentiment of a review', 'Many inputs, one output'], ['Tag every word', 'Many inputs, many outputs'], ['Generate music from a seed', 'One input, many outputs'], ['Translate a sentence', 'Sequence in, different-length sequence out']]),
      mc('Why can an RNN process sequences of any length?', ['It applies the same step repeatedly', 'It pads everything to 1,000', 'It ignores long inputs', 'It has one neuron per position'], 'Weight sharing across time.')),

    L('Training and its problem',
      info('Backpropagation through time', 'To train, we **unroll** the RNN: imagine one copy of the network per time step, chained together. Then ordinary backpropagation runs backwards through all the copies.\n\nThis is **backpropagation through time (BPTT)**.'),
      mc('In BPTT, the gradient at an early time step is…', ['A product of many terms, one per later step', 'Always exactly 1', 'Independent of later steps', 'Computed first'], 'Chain rule through every step in between.'),
      type('A gradient is multiplied by 0.5 at each of 10 steps. Roughly what fraction remains? Answer as 1/N.', ['1/1024', '1/1000'], '0.5 to the power 10. It vanishes quickly.'),
      mc('Gradients that shrink toward zero over many steps are called…', ['Vanishing gradients', 'Exploding gradients', 'Dead neurons', 'Overfitting'], 'The network then cannot learn long-range dependencies.'),
      mc('The loss suddenly becomes NaN while training an RNN. Likely cause and fix?', ['Exploding gradients; clip the gradient norm', 'Vanishing gradients; add more layers', 'Too little data; add dropout', 'The tokenizer; retrain it'], 'Clipping caps the size of each update.'),
      fillc('torch.nn.utils.clip_grad_norm_(model.parameters(), ___=1.0)', ['max_norm', 'min_norm', 'lr', 'dropout'], 'Rescales gradients whose norm exceeds the limit.'),
      tf('Gradient clipping solves the vanishing-gradient problem.', false, 'It only tames explosions. Vanishing needs a different architecture.'),
      mc('What is truncated BPTT?', ['Backpropagating through only a limited number of recent steps', 'Removing the hidden state', 'Training without gradients', 'Clipping the inputs'], 'It bounds memory and compute for very long sequences.')),

    L('LSTM and GRU',
      info('A memory with gates', 'The **LSTM** adds a second state, the **cell state**: a conveyor belt of long-term memory.\n\nThree **gates**, each a number between 0 and 1, control it:\n\n- **forget gate:** how much old memory to keep\n- **input gate:** how much new information to write\n- **output gate:** how much memory to reveal'),
      match('Match the gate to its job', [['Forget gate', 'Erase parts of the cell state'], ['Input gate', 'Write new information'], ['Output gate', 'Expose memory as the hidden state'], ['Candidate (tanh)', 'Propose new values to write']]),
      fillc('c = f * c + i * ___', ['g', 'o', 'h', 'x'], 'Old memory kept by the forget gate, plus the candidate gated by the input gate.'),
      mc('Which activation makes a gate behave like a soft switch between 0 and 1?', ['Sigmoid', 'ReLU', 'Softmax over time', 'Identity'], 'Sigmoid outputs values in (0, 1).'),
      info('Why it helps', 'In a plain RNN the state is squashed and multiplied at every step. In an LSTM the cell state is updated mostly by **addition**:\n\n```\nc = f * c + i * g\n```\n\nIf the forget gate stays near 1, information and gradients pass almost unchanged across many steps.'),
      mc('The forget gate is 1 and the input gate is 0. What happens to the cell state?', ['It is copied unchanged', 'It is reset to zero', 'It doubles', 'It becomes the input'], 'c = 1 * c + 0 * g.'),
      mc('How does a GRU differ from an LSTM?', ['Two gates and no separate cell state, so fewer parameters', 'It has five gates', 'It cannot be trained with gradients', 'It reads the sequence backwards only'], 'Update and reset gates.'),
      tf('A bidirectional RNN can be used for real-time streaming prediction at each step.', false, 'The backward pass needs the future of the sequence.'),
      order('Order one LSTM step', ['Compute gates i, f, o and candidate g from x and the previous h', 'Update the cell: c = f * c + i * g', 'Compute the hidden state: h = o * tanh(c)', 'Pass h and c to the next time step'], 'Gates, memory, output.')),

    L('RNNs in practice and interview level',
      info('Where RNNs still win', 'Transformers took over language. RNNs keep a place where:\n\n- data arrives as a **stream** and you need an answer at every step\n- the device is **small**: a GRU with a few thousand weights fits a microcontroller\n- memory per step must be **constant**'),
      mc('A vibration sensor on a motor ECU must be classified every 10 ms with 20 kB of RAM. Reasonable model?', ['A small GRU or 1-D CNN', 'A 7-billion-parameter LLM', 'A vision transformer', 'No model can run there'], 'Tiny recurrent or convolutional models are standard on microcontrollers.'),
      mc('PyTorch `nn.LSTM(batch_first=True)` expects input of shape…', ['(batch, time, features)', '(time, features)', '(features, batch, time)', '(batch, features)'], 'A frequent source of silent bugs. Check it.'),
      mc('For streaming inference with an RNN you must…', ['Keep the hidden state between calls', 'Reset the state at every step', 'Re-run the whole history each time', 'Shuffle the stream'], 'The state is the memory; carry it forward.'),
      info('Sequence-to-sequence and attention', 'Translation used an **encoder** RNN to compress the input into one vector and a **decoder** RNN to generate the output. One vector was a bottleneck.\n\n**Attention** let the decoder look back at every encoder state. Then the transformer removed recurrence and kept only attention.'),
      mc('What bottleneck did attention remove from encoder-decoder RNNs?', ['Squeezing the whole input into one fixed vector', 'The need for training data', 'The softmax layer', 'The embedding layer'], 'The decoder can now consult all input positions.'),
      mc('Why do transformers train faster than RNNs on GPUs?', ['All positions are processed in parallel', 'They have fewer parameters', 'They skip backpropagation', 'They use smaller batches'], 'An RNN must step through time sequentially.'),
      order('Order a strong answer to "Explain an LSTM"', ['It keeps a cell state as long-term memory', 'Forget, input and output gates control what is erased, written and exposed', 'The cell update is additive, so gradients survive many steps', 'That solves the vanishing-gradient problem of vanilla RNNs'], 'Mechanism first, then why it matters.'),
      mc('Your LSTM overfits a small dataset. Sensible steps?', ['Dropout, smaller hidden size, early stopping, more data', 'More layers and a larger hidden size', 'Remove the validation set', 'Train much longer'], 'Standard regularisation applies.')),

    L('Shapes, sizes and training tricks',
      info('Sizes of an LSTM', 'An LSTM has four blocks (three gates and the candidate). Each has an input matrix (hidden × input), a recurrent matrix (hidden × hidden) and, in PyTorch, **two** bias vectors.\n\n```\nparameters = 4 × hidden × (input + hidden + 2)\n```\n\nA GRU has three blocks instead of four, so `3 × hidden × (input + hidden + 2)`.\n\nFor `nn.LSTM(10, 20, batch_first=True)` the outputs for a batch of shape (8, 50, 10) are `out` with shape (8, 50, 20) and the final states `h` and `c` with shape (1, 8, 20).'),
      mc('What are the shapes of out and h here?', ['out (8, 50, 20) and h (1, 8, 20)', 'out (8, 50, 10) and h (8, 20)', 'out (50, 8, 20) and h (8, 1, 20)', 'out (8, 20) and h (50, 8, 20)'], 'out holds the hidden state at every step; h holds only the last one per layer.', 'lstm = nn.LSTM(10, 20, batch_first=True)\nx = torch.randn(8, 50, 10)      # (batch, time, features)\nout, (h, c) = lstm(x)'),
      type('How many parameters does nn.LSTM(10, 20) have, using the formula with two biases?', ['2560', '2,560'], '4 × 20 × (10 + 20 + 2).'),
      info('Training sequence models', '**Teacher forcing:** when training a decoder, feed it the true previous token, not its own guess. Training is stable, but at inference the model sees its own mistakes, a mismatch called **exposure bias**.\n\n**Padding:** sequences in a batch are padded to equal length. Use masks or `pack_padded_sequence` so padding does not change the result.\n\n**Bidirectional:** one RNN reads forwards and one backwards, and their states are concatenated.'),
      mc('What is exposure bias?', ['Training sees true previous tokens but inference sees the model’s own mistakes', 'The model sees too much data', 'Gradients are exposed to noise', 'The hidden state is shared between samples'], 'Scheduled sampling and similar tricks reduce the gap.'),
      tf('Padded positions should be masked or packed so they do not influence the final hidden state.', true, 'Otherwise a sequence’s result depends on how much padding it received.'),
      match('Match the term to its meaning', [['Teacher forcing', 'Feed the true previous token during training'], ['pack_padded_sequence', 'Skip padding when running the RNN'], ['Bidirectional RNN', 'Forward and backward states concatenated'], ['Stacked RNN', 'Each layer’s output is the next layer’s input']]),
      mc('A bidirectional LSTM with hidden size 64 is used. How many features does each output step have?', ['128', '64', '32', '256'], 'Forward and backward states are concatenated: 2 × 64.'),
      type('How many parameters does nn.GRU(10, 20) have?', ['1920', '1,920'], '3 × 20 × (10 + 20 + 2).')),

    L('Common mistakes and debugging',
      info('State, graphs and padding', 'RNN bugs hide in three places: the **hidden state** carried between batches, the **padding** in batches of unequal length, and **evaluation** that looks good only because the model copies the last value.\n\nAll three train happily and fail quietly.'),
      mc('This loop trains on long chunks and carries the hidden state between them. What fails on the second iteration?', ['backward() tries to go through the graph of the previous chunk, which was already freed', 'The learning rate is too high', 'The batch is too large', 'Nothing fails'], 'Detach the state so each chunk’s backward pass stops at the chunk boundary.', 'h = torch.zeros(1, B, 64)\nfor x, y in chunks:\n    out, h = rnn(x, h)\n    loss = loss_fn(out, y)\n    loss.backward()'),
      fillc('h = h.___()   # cut the graph but keep the values', ['detach', 'clone', 'zero_', 'cpu'], 'detach() keeps the state’s values but stops gradients flowing into earlier chunks.'),
      mc('Sequences are right-padded and you classify using out[:, -1]. What is the problem?', ['For shorter sequences that is a padded position, not the last real step', 'It returns the first step', 'out has no time dimension', 'Nothing, the last step is always the last real one'], 'Index with each sequence’s real length, or use packed sequences.'),
      type('Four sequences of lengths 10, 20, 30 and 40 are padded to length 40. How many padded positions are in the batch?', ['60'], '4 × 40 - 100 = 60, which is 37.5% of the batch.'),
      info('Looks good, but is it?', 'On next-value prediction a model that simply **copies the last input** already scores very well, so a high R² proves little. Always compare with the naive forecast.\n\nAlso check: do not shuffle when the hidden state is carried across batches, clip gradients **after** backward and **before** the step, and consider starting the LSTM forget-gate bias at 1 so memory is kept early on.'),
      mc('An LSTM predicts the next temperature with R² = 0.98, and the naive last-value forecast also gets 0.98. What does this tell you?', ['The model has learned little beyond persistence', 'The model is excellent', 'The naive forecast is broken', 'R² is always 0.98'], 'A model must beat the baseline to be useful.'),
      tf('Shuffling the batches is harmless when the hidden state is carried over from one batch to the next.', false, 'The carried state would belong to an unrelated sequence.'),
      order('Order one training step with gradient clipping', ['optimizer.zero_grad()', 'loss = loss_fn(model(x), y)', 'loss.backward()', 'torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)', 'optimizer.step()'], 'Clip after the gradients exist and before they are applied.')),

    L('Case study: predicting pump failures',
      info('The problem', 'A utility runs 500 pumps. Each logs 8 sensors every minute (vibration, temperature, pressure and so on). An unplanned failure is expensive; planned maintenance is cheap.\n\nThe goal: raise an alert when a pump is likely to fail within the next 24 hours.'),
      type('You feed the model the last 60 minutes of 8 sensors. How many numbers are in one input window?', ['480'], '60 × 8.'),
      mc('How do you define the training label?', ['For each window, 1 if the pump fails within the next 24 hours, otherwise 0', 'The average sensor value', 'The pump’s name', 'The number of windows'], 'Turn a vague goal into a concrete supervised label.'),
      mc('How should you split the data into train, validation and test?', ['By pump, so no pump appears in more than one split', 'Randomly by window', 'By sensor', 'Alphabetically by timestamp'], 'Overlapping windows from the same pump are near duplicates, so random splits leak.'),
      info('Rare events', 'Failures are rare: say 0.5% of windows are positive. A model that never raises an alert is 99.5% accurate and worthless.\n\nUse **class weights** or oversampling, and judge the model by **precision and recall** of the alerts. Technicians stop trusting a system that cries wolf, so the false-alarm rate is part of the design.'),
      type('Out of 200,000 windows, 0.5% are positive. How many positive windows?', ['1000', '1,000'], '200,000 × 0.005.'),
      order('Order the project steps', ['Label each window: does the pump fail within 24 hours?', 'Split the pumps into train, validation and test sets', 'Normalise the sensors with statistics from the training pumps', 'Train a small GRU with class weights', 'Choose the alert threshold from validation precision and recall', 'Run in shadow mode before real alerts'], 'Leakage prevention comes before modelling; real-world testing comes last.'),
      mc('In production the model must update every minute for 500 pumps. How do you cut compute?', ['Keep each pump’s hidden state and feed only the newest reading, about 60 times less work than re-running the window', 'Re-run the whole 60-minute window every minute', 'Retrain every minute', 'Use a bigger model'], 'Carrying the state is the natural strength of an RNN.'),
      mc('Alerts have 20% precision and technicians start ignoring them. What do you change?', ['Raise the threshold to trade some recall for precision, agreed with the maintenance team', 'Lower the threshold to alert more', 'Remove monitoring', 'Retrain with fewer pumps'], 'Choose the operating point from the cost of false alarms and misses.'),
      mc('Before building the GRU, which baseline is most useful?', ['A simple rule on a rolling mean of vibration, plus a gradient-boosted model on window statistics', 'No baseline is needed', 'A random alert', 'A larger GRU'], 'The neural model must justify its extra complexity.')),

    L('Interview drill: recurrent networks',
      info('How questions escalate', 'Recurrent-network questions usually start at "explain an LSTM", then go to parameter counts, gradient problems, alternatives such as temporal convolutions, and finally "would you use this today?".\n\nKnow the numbers: gates, parameter formula, and receptive-field arithmetic.'),
      mc('A GRU has what share of an LSTM’s recurrent parameters for the same sizes?', ['Three quarters', 'Half', 'The same', 'Double'], 'Three blocks instead of four.'),
      tf('An LSTM completely removes the vanishing-gradient problem.', false, 'It mitigates it, but very long dependencies of thousands of steps are still hard.'),
      mc('Interviewer: "Clip gradients by norm or by value?"', ['By norm, because it rescales the whole vector and keeps its direction', 'By value, because it keeps the direction', 'Neither changes anything', 'By norm, because it makes gradients larger'], 'Clipping each value separately distorts the direction of the update.'),
      info('Numbers to have ready', '**LSTM parameters:** 4 × hidden × (input + hidden + 2) in PyTorch.\n\n**Temporal convolutional network (TCN):** causal convolutions whose dilation doubles per layer. Receptive field = 1 + (kernel - 1) × (sum of the dilations).\n\nA TCN trains in parallel over time and has no recurrent state, which makes it a strong rival for sensor streams.'),
      type('nn.LSTM with input 1 and hidden size 32 has how many parameters?', ['4480', '4,480'], '4 × 32 × (1 + 32 + 2).'),
      type('A causal convolution with kernel size 3 and dilations 1, 2, 4 and 8. What is the receptive field?', ['31'], '1 + 2 × (1 + 2 + 4 + 8).'),
      match('Match the follow-up to its answer', [['Truncated BPTT: what is the cost?', 'It cannot learn dependencies longer than the window'], ['Why start the forget-gate bias at 1?', 'The cell remembers by default, so gradients flow early in training'], ['What is exposure bias?', 'Training sees true history, inference sees its own mistakes'], ['Why consider a 1-D CNN instead?', 'It parallelises over time and needs no recurrent state']]),
      order('Order a strong answer to "RNN or transformer for a streaming sensor problem?"', ['Clarify latency, memory and the amount of data', 'Note that an RNN needs constant memory and one step per sample', 'Note that a transformer needs a window whose attention cost grows with its square', 'Propose benchmarking a small GRU or TCN against a small transformer', 'Decide by accuracy at the device’s budget'], 'Requirements first, then trade-offs, then evidence.'))
  ],

  'ts-transformers': [
    L('From words to measurements',
      info('The same machine, new food', 'A transformer turns a sequence of **tokens** into vectors and lets every token look at every other one with **attention**.\n\nFor text a token is a piece of a word. For a time series we must decide: what is a token?'),
      mc('What does self-attention let each position do?', ['Look at all other positions and weight them by relevance', 'Look only at the previous position', 'Ignore the sequence', 'Sort the sequence'], 'That is how long-range patterns are captured in one step.'),
      mc('Why is one time step a weak token?', ['A single number carries almost no meaning by itself', 'Numbers cannot be embedded', 'It is too large', 'Transformers reject floats'], 'A word has meaning alone; one sensor reading does not.'),
      info('Patching', '**Patching** groups consecutive points, for example 16 at a time, into one token. A linear layer embeds each patch into a vector.\n\nBenefits: far fewer tokens (cheaper attention) and each token describes a local shape, like a rise or a spike.'),
      type('A window of 512 points is cut into non-overlapping patches of 16. How many tokens?', ['32'], '512 / 16.'),
      mc('Attention cost grows with the square of the number of tokens. Going from 512 tokens to 32 cuts that cost by about…', ['256 times', '16 times', '2 times', 'Nothing'], '(512 / 32) squared.'),
      tf('Self-attention knows the order of its tokens without any extra information.', false, 'It is order-blind; positional encodings must be added.'),
      match('Match the idea', [['Patch', 'A group of consecutive time steps used as one token'], ['Embedding', 'Turning a token into a vector'], ['Positional encoding', 'Telling the model where each token sits'], ['Attention', 'Weighting other tokens by relevance']])),

    L('Time, order and no peeking',
      info('Cyclical time', 'Hour 23 and hour 0 are one hour apart, but as numbers they differ by 23. Put time on a **circle**:\n\n```\nsin(2π · hour / 24),  cos(2π · hour / 24)\n```\n\nNow neighbouring hours get neighbouring features.'),
      mc('Why use both sine and cosine?', ['Sine alone gives the same value for two different hours', 'Cosine is faster', 'It doubles accuracy', 'Tradition only'], 'Together they identify every point on the circle uniquely.'),
      fillc('sin_dow = math.sin(2 * math.pi * weekday / ___)', ['7', '24', '12', '365'], 'The period of the weekday cycle.'),
      info('Do not look ahead', 'During training the whole series is in memory. If position `i` can attend to position `i+1`, the model simply reads the answer.\n\nA **causal mask** allows attention only to the current and earlier positions.'),
      mc('In a causal mask, position 2 (counting from 0) may attend to positions…', ['0, 1 and 2', '2, 3 and 4', 'All positions', 'Only 2'], 'Itself and the past.'),
      mc('The causal mask as a matrix is…', ['Lower triangular', 'Upper triangular with zeros on the diagonal', 'The identity only', 'All ones'], 'Row i has ones up to column i.'),
      mc('An alternative to a causal mask for forecasting is…', ['Feed only the history to an encoder and predict the whole horizon', 'Shuffle the input', 'Remove positional encodings', 'Train on the test set'], 'The future is never in the input, so nothing can leak.'),
      tf('Normalising each input window (subtract its mean, divide by its standard deviation) helps with level shifts.', true, 'Add the statistics back to the output afterwards.')),

    L('The model zoo and a reality check',
      info('Names you may be asked about', '- **Informer / Autoformer:** cheaper attention for long sequences.\n- **Temporal Fusion Transformer (TFT):** mixes static features, known future inputs and history; interpretable.\n- **PatchTST:** patching plus treating each variable separately.\n- **iTransformer:** each variable becomes a token.\n- **Chronos, TimesFM, Moirai:** pre-trained foundation models.'),
      match('Match the model to its key idea', [['PatchTST', 'Patches as tokens, channel independence'], ['TFT', 'Static, known-future and observed inputs with variable selection'], ['iTransformer', 'One token per variable'], ['Chronos / TimesFM', 'Pre-trained on many series, zero-shot forecasts']]),
      info('The linear surprise', 'In 2022 a paper showed that a **one-layer linear model** (DLinear) matched or beat several transformer forecasters on the standard benchmarks.\n\nLesson: a fancy architecture is not evidence. Always compare with strong simple baselines.'),
      mc('What should you conclude from the DLinear result?', ['Benchmark against simple baselines before claiming a gain', 'Transformers never work for time series', 'Linear models are always best', 'Benchmarks do not matter'], 'Later designs such as PatchTST did beat it, with evidence.'),
      mc('What does "zero-shot forecasting" mean for a foundation model?', ['Forecasting a new series without training on it', 'Training with zero data', 'Predicting zeros', 'Using no model'], 'It was pre-trained on many other series.'),
      mc('Direct multi-step versus autoregressive forecasting?', ['Direct predicts the whole horizon at once; autoregressive feeds its own predictions back in', 'They are identical', 'Autoregressive cannot forecast more than one step', 'Direct needs a decoder mask'], 'Autoregressive errors accumulate over the horizon.'),
      tf('Transformers usually need more training data than gradient-boosted trees to work well.', true, 'They have weaker built-in assumptions about the data.'),
      mc('You have 3 years of daily data for a single shop. Best starting point?', ['Seasonal naive and exponential smoothing, perhaps a pre-trained model zero-shot', 'Train a large transformer from scratch', 'A vision model', 'Skip baselines'], 'About a thousand points is far too few to train a transformer.')),

    L('Applications and interview level',
      info('More than forecasting', 'The same encoder serves other tasks:\n\n- **Anomaly detection:** forecast or reconstruct the signal; a large error flags an anomaly.\n- **Classification:** label a window, for example a driving manoeuvre.\n- **Imputation:** fill in missing values.'),
      mc('An autoencoder trained only on normal sensor data reconstructs a new window very badly. That suggests…', ['The window is anomalous', 'The window is perfectly normal', 'The model is overfitted to anomalies', 'Nothing'], 'It never learned to reproduce that pattern.'),
      mc('Your anomaly score flickers above and below the threshold on every sample. Fix?', ['Smooth the score or require several consecutive exceedances', 'Lower the threshold to zero', 'Retrain on anomalies only', 'Remove the threshold'], 'Debouncing avoids alarm chatter.'),
      mc('With very few labelled anomalies, how do you evaluate honestly?', ['Event-level precision and recall on known incidents, plus expert review of top alerts', 'Accuracy over all samples', 'Training loss', 'Do not evaluate'], 'Accuracy is meaningless when anomalies are rare.'),
      info('Getting it onto a device', 'Sequence length drives memory and compute. To deploy at the edge: shorter context, larger patches, fewer layers, quantisation, distillation into a small student.\n\nFor streaming, cache computations for the part of the window that did not change.'),
      mc('Which change reduces a time-series transformer’s compute the most?', ['Fewer tokens, through larger patches or a shorter context', 'A longer context', 'More attention heads', 'Float64 weights'], 'Attention cost is quadratic in tokens.'),
      order('Order a strong answer to "How would you forecast with a transformer?"', ['Tokenise the series into patches and embed them', 'Add positional and cyclical time features', 'Prevent look-ahead and normalise each window', 'Train across many related series', 'Benchmark against naive, linear and tree baselines'], 'Design, safeguards, then evidence.'),
      mc('Interviewer: "Why not always use a transformer?" Best answer?', ['They need lots of data and compute, and simple models often match them; I choose by backtest', 'Transformers are old', 'They cannot handle numbers', 'They are illegal in automotive'], 'Show judgement, not fashion.'),
      mc('Covariates known in advance, such as holidays or planned promotions, are best used as…', ['Inputs for the forecast horizon', 'Targets', 'Noise to remove', 'Positional encodings'], 'Models such as TFT have a dedicated path for known-future inputs.')),

    L('Normalising windows, counting tokens and choosing a loss',
      info('Instance normalisation', 'Series drift: a sensor’s level today may differ from last month’s. **Instance normalisation** (often called RevIN) standardises each input window with its own mean and standard deviation, runs the model, then **reverses** the transformation on the output:\n\n```\nx_norm = (x - mean) / std\ny = model(x_norm) * std + mean\n```\n\nThe model then learns shapes, not absolute levels.'),
      type('A window has mean 100 and standard deviation 10. The model outputs 1.5 in normalised units. What is the forecast in the original units?', ['115'], '1.5 × 10 + 100.'),
      mc('Why does per-window normalisation help with non-stationary data?', ['The model sees the shape of the window and is not thrown by a changed level or scale', 'It removes the need for training', 'It makes the series shorter', 'It adds new features'], 'Level shifts are removed on the way in and restored on the way out.'),
      info('Counting patches', 'With a window of length L, patch length P and stride S the number of tokens is:\n\n```\ntokens = floor((L - P) / S) + 1\n```\n\nA stride smaller than P gives **overlapping** patches. Many models treat each variable as its own series (**channel independence**) and share the weights: a batch of 32 windows with 7 variables becomes 224 sequences.'),
      type('L = 336, P = 16, S = 8. How many tokens?', ['41'], '(336 - 16) / 8 + 1 = 41.'),
      mc('What is the main benefit of channel independence for a dataset with few samples?', ['Shared weights see many more sequences and do not memorise spurious relations between variables', 'It uses more parameters', 'It removes the need for normalisation', 'It forces causal masking'], 'Fewer assumptions about cross-variable relations means less overfitting.'),
      match('Match the loss to its behaviour', [['MSE', 'Punishes big errors, targets the mean'], ['MAE', 'Robust to outliers, targets the median'], ['Pinball (quantile) loss', 'Targets a chosen percentile, for intervals'], ['Negative log-likelihood of a distribution', 'Learns a mean and a spread for probabilistic forecasts']]),
      tf('Learned positional embeddings usually cannot be used for contexts longer than those seen in training.', true, 'There is no learned embedding for unseen positions.'),
      type('41 tokens of dimension 64 are flattened and mapped by one linear layer (with bias) to a 96-step forecast. How many parameters does that head have?', ['252000', '252,000'], '(41 × 64) × 96 + 96 = 2,624 × 96 + 96.')),

    L('Common mistakes and debugging',
      info('Leaks hide in preprocessing', 'Time-series transformers are not safe from the usual leaks. Normalising a window together with its **target** lets the future shape the inputs. Random window splits also leak: with stride 1, neighbouring windows share almost every value, so a validation window is nearly a copy of a training window.\n\nSplit by **time**, and compute statistics from the history part only.'),
      mc('What is the leak in this code?', ['The statistics include the 24 horizon values, which are the target', 'The window is too short', 'mean is the wrong statistic', 'There is no leak'], 'Only the 96 history values may be used.', 'window = series[t : t + 96 + 24]     # 96 history + 24 horizon\nmu, sd = window.mean(), window.std()  # computed over all 120 values'),
      fill('Normalisation statistics must come from the ___ part of the window only.', ['history', 'horizon', 'whole', 'target'], 'The horizon is unknown at forecast time.'),
      type('Two windows of length 100 start one step apart. How many values do they share?', ['99'], 'They overlap on everything except one value at each end.'),
      info('Silent shape and mask bugs', '`reshape` rearranges memory but does **not** swap axes; to swap time and variables use `transpose` or `permute`. The result of a wrong reshape has the right shape and scrambled values.\n\nA mask that hides every position in a row makes `softmax` of all minus infinity: **NaN**. Always leave at least one position visible, for example the current one.'),
      fillc('x = x.___(1, 2)   # (batch, time, vars) becomes (batch, vars, time)', ['transpose', 'reshape', 'view', 'flatten'], 'transpose swaps two axes; reshape only reinterprets memory.'),
      mc('Some training rows give NaN losses only for short, heavily padded sequences. What is a likely cause?', ['A row is entirely masked, so softmax divides zero by zero', 'The learning rate is too small', 'The model has too many heads', 'The batch is too small'], 'Keep one position unmasked or handle empty rows.'),
      tf('Reporting the error only in normalised units is enough for the business.', false, 'Stakeholders need errors in real units, and normalised errors hide scale.'),
      mc('The forecast is nearly a flat line near the mean, and the naive forecast beats it. What do you try first?', ['Check normalisation and learning rate, then compare with simple baselines', 'Add more heads', 'Remove the training data', 'Increase the horizon'], 'A collapsed model usually means optimisation or input-scaling problems.')),

    L('Case study: day-ahead electricity demand',
      info('The problem', 'A grid operator forecasts hourly demand for each of 1,000 feeders, 24 hours ahead, to plan generation. There are three years of hourly history per feeder, and a weather service provides **temperature forecasts** for tomorrow.\n\nErrors are costly in both directions: too little reserve risks blackouts, too much wastes fuel.'),
      type('Three years of hourly data (365 days a year) per feeder. How many points?', ['26280', '26,280'], '3 × 365 × 24.'),
      mc('What is the first baseline?', ['Seasonal naive using the same hour last week', 'The overall mean', 'A transformer', 'Yesterday’s daily total spread equally'], 'Weekday and weekend patterns make the weekly lag stronger than the daily one.'),
      info('Design choices', 'Train **one model across all 1,000 feeders** with shared weights: 26 million points are enough for a patch-based transformer, while one feeder is not.\n\nUse a look-back of one week (168 hours) cut into patches of 12 hours with stride 12. Feed calendar features, and the temperature **forecast** for the horizon as a known-future input.'),
      type('A 168-hour look-back is cut into non-overlapping 12-hour patches. How many tokens?', ['14'], '168 / 12.'),
      mc('Training used the observed temperature, but at serving time only a forecast is available. What is the risk?', ['Train-serve skew: the model learns from cleaner weather than it gets in production', 'None, observed and forecast values are identical', 'The model refuses to run', 'The look-back is too short'], 'Train on archived forecasts to match what will be available.'),
      order('Order the evaluation', ['Hold out the most recent year as the test period', 'Backtest with rolling origins that include winter and summer', 'Score MASE against the weekly seasonal naive, per feeder and per hour', 'Check errors on holidays and extreme-weather days', 'Run in shadow mode next to the current system'], 'With only three winters, seasonal coverage in the backtest matters.'),
      mc('Meter outages were recorded as zeros. What do you do with them?', ['Mark them as missing and exclude them from the loss', 'Keep them as true demand', 'Replace them with the maximum', 'Leave them and hope'], 'A zero from a faulty meter is not demand.'),
      mc('The transformer reaches MASE 0.92, a boosted-tree model reaches 0.90, and the transformer costs ten times more to run. What do you choose?', ['The boosted-tree model, or an ensemble if it adds value, and report the evidence', 'The transformer because it is newer', 'Neither', 'Whichever is larger'], 'Complexity must buy a measurable gain.')),

    L('Interview drill: transformers for time series',
      info('What gets asked', 'Interviewers test whether you know where transformers help, where they do not, and how you would prove a gain. Expect questions on channel handling, probabilistic outputs, missing data, and deployment size.\n\nEvery strong answer ends with how you would **measure** it.'),
      mc('Interviewer: "Why can channel-independent models beat channel-mixing ones on small datasets?"', ['Shared weights see many more sequences and mix fewer spurious cross-variable patterns', 'They use attention across variables', 'They have more parameters', 'They need no training'], 'Fewer assumptions mean less overfitting.'),
      tf('Making the look-back window longer always improves a transformer forecaster’s accuracy.', false, 'Several studies found that many transformer forecasters did not improve, and sometimes got worse, with longer look-backs.'),
      type('In an iTransformer each of 7 variables is one token. How many attention scores does one head compute for one sample?', ['49'], '7 × 7.'),
      match('Match the question to the strongest answer', [['How do you handle missing values?', 'Mask them, impute using only the past, or train with masked reconstruction'], ['How do you evaluate a zero-shot foundation model?', 'Backtest it on your own series against seasonal naive and a tuned local model'], ['How do you get probabilistic forecasts?', 'Quantile heads with pinball loss, or a distribution head with log-likelihood'], ['Why avoid purely autoregressive multi-step forecasts?', 'Errors compound as predictions are fed back in']]),
      info('Getting small', 'Deployment questions are arithmetic. Float32 uses 4 bytes per weight, float16 uses 2, and int8 uses 1.\n\n**Quantisation** stores weights in lower precision and **distillation** trains a small student to imitate a large teacher. Both trade a little accuracy for a lot of size and speed.'),
      type('A model has 2,000,000 parameters in float32. How many megabytes (1 MB = 1,000,000 bytes)?', ['8'], '2,000,000 × 4 bytes.'),
      mc('Roughly how much smaller does int8 quantisation make a float32 model?', ['About 4 times', 'About 2 times', 'About 100 times', 'It does not change'], '8 bits instead of 32.'),
      order('Order a strong answer to "How would you prove a transformer is worth deploying?"', ['Define the metric and the decision it supports', 'Build naive, linear and boosted-tree baselines', 'Backtest every model on identical rolling windows', 'Report gains with their spread across windows and segments', 'Compare cost: latency, memory and upkeep', 'Run a shadow deployment before switching'], 'Evidence and cost, then a safe rollout.'))
  ]
};
